solution.solution.cpp:
long long sharedSavings(long long codeBytes, int processes)
{
    if (processes <= 1) return 0;
    return codeBytes * (processes - 1);
}

long long pagesFor(long long bytes)
{
    if (bytes <= 0) return 0;
    return (bytes + 4095) / 4096;
}

unitTests:
TEST("four processes") { CHECK_EQ(sharedSavings(1'000'000, 4), 3'000'000LL); }
TEST("one process saves nothing") { CHECK_EQ(sharedSavings(500, 1), 0LL); CHECK_EQ(sharedSavings(500, 0), 0LL); }
TEST("many processes") { CHECK_EQ(sharedSavings(2'000'000, 300), 598'000'000LL); }
TEST("whole pages") { CHECK_EQ(pagesFor(4096), 1LL); CHECK_EQ(pagesFor(8192), 2LL); }
TEST("part pages round up") { CHECK_EQ(pagesFor(1), 1LL); CHECK_EQ(pagesFor(4097), 2LL); }
TEST("nothing") { CHECK_EQ(pagesFor(0), 0LL); }

